// Official Avenida floor plans use their own level numbering.
// Affine alignment of the shared footprint to OSM; not a surveyed registration.
let area='station',mallLevel=0,mallSelected=null,mallReady=false,mallError=false;
const mallFloors=[],mallNames={},stationRenderer=render;
const mallMatrix='matrix(.4057 .08985 -.08654 .4282 177.64 214.50)';
const mallFloorOf=id=>({'1013':0,'1016':1,'1019':2})[id.slice(1,5)];
const floorName=n=>n===0?(english?'Ground floor':'Parter'):'+'+n;
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]);
function cameraMall(){zoom=2.2;pan=[(525-357)*zoom,(360-396)*zoom]}
function levelButtons(){const levels=area==='mall'?[2,1,0]:[1,0,-1];$('.levels').innerHTML=levels.map(n=>`<button data-level="${n}" class="${n===(area==='mall'?mallLevel:level)?'active':''}" aria-pressed="${n===(area==='mall'?mallLevel:level)}">${n>0?'+':''}${n}<span>${area==='mall'?(n===0?(english?'Ground':'Parter'):(english?'Floor':'Piętro')):({1:english?'Hall':'Hala',0:english?'Platforms':'Perony','-1':english?'Tunnel':'Tunel'})[n]}</span></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(area==='mall'){mallLevel=+b.dataset.level;mallSelected=null;$('#mall-selection').textContent=english?'Tap a unit on the map.':'Dotknij lokalu na mapie.'}else level=+b.dataset.level;render()})}
function selectMall(id){mallSelected=id;mallLevel=mallFloorOf(id);$('#mall-selection').textContent=(mallNames[id]||(+id.split('-')[1]>=10000?(english?'Service point — see icon':'Punkt usługowy — zobacz ikonę'):(english?'Unit without a description':'Lokal bez opisu')))+' · '+floorName(mallLevel);render()}
function mallResults(){const q=$('#mall-search').value.trim().toLocaleLowerCase('pl');const box=$('#mall-results');box.replaceChildren();if(!q)return;const matches=Object.entries(mallNames).filter(([,name])=>name.toLocaleLowerCase('pl').includes(q)).slice(0,8);if(!matches.length){box.textContent=english?'No matching units.':'Nie znaleziono lokalu.';return}for(const [id,name]of matches){const b=document.createElement('button');b.textContent=name+' · '+floorName(mallFloorOf(id));b.onclick=()=>selectMall(id);box.append(b)}}
function updateAreaText(){const mall=area==='mall';const legend=$('.map-bottom');const keys=legend.querySelectorAll(':scope > span');keys[0].innerHTML='<i class="key platform"></i>'+(mall?(english?'Units':'Lokale'):(english?'Platform':'Peron'));keys[1].innerHTML='<i class="key path"></i>'+(mall?(english?'Selected unit':'Wybrany lokal'):(english?'Demo route':'Trasa demo'));keys[2].textContent=mall?(english?'Icons: lifts & escalators':'Ikony: windy i schody'):(english?'▤ Stairs on both sides':'▤ Schody po obu stronach');$('#area-station').textContent=english?'Station':'Dworzec';$('#area-mall').textContent='Avenida';$('.intro').innerHTML=mall?(english?'Three floors. One shared map.<br>Tap a unit to see its name.':'Trzy piętra. Jedna wspólna mapa.<br>Dotknij lokalu, aby zobaczyć nazwę.'):(english?'Choose your start and platform.<br>See how the levels connect.':'Wybierz miejsce startu i peron.<br>Zobacz, jak łączą się poziomy.');$('.notice').textContent=mall?(english?'OFFICIAL FLOOR PLANS • Alignment is approximate. Routes inside the mall are not available yet.':'OFICJALNE PLANY PIĘTER • Dopasowanie przybliżone. Trasy wewnątrz centrum jeszcze niedostępne.'):(english?'PROTOTYPE • OSM geometry. Demo routes — require on-site verification.':'PROTOTYP • Geometria OSM. Trasy demonstracyjne — do weryfikacji na dworcu.');$('#mall-search').setAttribute('aria-label',english?'Search Avenida units':'Szukaj lokalu w Avenidzie');$('label[for="mall-search"]').textContent=english?'FIND A UNIT':'ZNAJDŹ LOKAL';$('.mall-hint').textContent=english?'Ground, +1 and +2 follow Avenida floor labels. Connection to station levels needs verification.':'Parter, +1 i +2 według oznaczeń Avenidy. Powiązanie wysokości z dworcem wymaga weryfikacji.';$('.source-link').textContent=english?'Official Avenida map ↗':'Oficjalny plan Avenidy ↗';if(mallSelected)$('#mall-selection').textContent=(mallNames[mallSelected]||(english?'Unit without a description':'Lokal bez opisu'))+' · '+floorName(mallLevel);}
function setArea(next){area=next;const mall=area==='mall';$('#station-controls').hidden=mall;$('#steps').hidden=mall;$('#mall-controls').hidden=!mall;$('#mall-credit').hidden=!mall;$('.map-panel').classList.toggle('mall-active',mall);$('#area-station').classList.toggle('active',!mall);$('#area-mall').classList.toggle('active',mall);$('#area-station').setAttribute('aria-pressed',String(!mall));$('#area-mall').setAttribute('aria-pressed',String(mall));if(mall)cameraMall();else{zoom=1;pan=[0,0]}render();}
render=function(){stationRenderer();levelButtons();updateAreaText();if(area!=='mall')return;$('#levelTitle').textContent='Avenida · '+floorName(mallLevel);const root=svg.querySelector(':scope > g');for(const child of root.children){child.setAttribute('opacity','.15');child.style.pointerEvents='none';child.setAttribute('aria-hidden','true');if(child.hasAttribute('tabindex'))child.setAttribute('tabindex','-1');for(const focusable of child.querySelectorAll('[tabindex]'))focusable.setAttribute('tabindex','-1')}if(!mallReady){$('#mall-selection').textContent=mallError?(english?'Could not load plans. Refresh to retry.':'Nie udało się wczytać planów. Odśwież stronę.'):(english?'Loading floor plans…':'Wczytywanie planów pięter…');return}const wrapper=document.createElementNS('http://www.w3.org/2000/svg','g');wrapper.setAttribute('transform',mallMatrix);wrapper.setAttribute('class','mall-plan');wrapper.innerHTML=mallFloors[mallLevel];root.append(wrapper);for(const el of wrapper.querySelectorAll('[data-shop]')){const id=el.dataset.shop;el.classList.toggle('selected',id===mallSelected);el.onclick=()=>selectMall(id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectMall(id)}}}const legend=$('.map-bottom');legend.classList.add('mall-legend');};
$('#area-station').onclick=()=>{$('.map-bottom').classList.remove('mall-legend');setArea('station')};$('#area-mall').onclick=()=>setArea('mall');$('#mall-search').oninput=mallResults;
const originalReset=$('#reset').onclick;$('#reset').onclick=()=>{if(area==='mall'){cameraMall();render()}else originalReset()};
async function loadMall(){try{const responses=await Promise.all([fetch('avenida/names.json'),...Array.from({length:3},(_,i)=>fetch('avenida/level-'+i+'.svg'))]);if(responses.some(r=>!r.ok))throw Error('Missing floor data');Object.assign(mallNames,await responses[0].json());const raw=await Promise.all(responses.slice(1).map(r=>r.text()));const colors={'#dedde0':'#293f34','#c7c8ca':'#293f34','#676767':'#809576','#d0de97':'#617c4d','#c5add4':'#697a57','#84c2cf':'#507c70','#fff':'#e6edce','#32304e':'#20352a','#2c304f':'#c5d6a9'};for(let i=0;i<3;i++){const doc=new DOMParser().parseFromString(raw[i],'image/svg+xml');if(doc.querySelector('parsererror'))throw Error('Invalid SVG');for(const e of doc.querySelectorAll('*')){if(['script','foreignObject','image'].includes(e.localName)){e.remove();continue}for(const a of [...e.attributes])if(a.name.startsWith('on')||a.name.includes('href'))e.removeAttribute(a.name);for(const a of ['fill','stroke'])if(colors[e.getAttribute(a)])e.setAttribute(a,colors[e.getAttribute(a)]);const id=e.id;if(/^p10(13|16|19)-\d+$/.test(id)){e.dataset.shop=id;e.setAttribute('class','mall-shop');e.setAttribute('role','button');e.setAttribute('tabindex','0');const name=mallNames[id]||(+id.split('-')[1]>=10000?(english?'Service point — see icon':'Punkt usługowy — zobacz ikonę'):(english?'Unit without a description':'Lokal bez opisu'));e.setAttribute('aria-label',name);const title=doc.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=name;e.append(title)}e.removeAttribute('id')}mallFloors[i]=doc.documentElement.innerHTML;}mallReady=true;$('#mall-selection').textContent=english?'Choose a floor or tap a unit.':'Wybierz piętro lub dotknij lokalu.';render()}catch(e){mallError=true;$('#mall-selection').textContent=english?'Floor plans could not load. Refresh the page to retry.':'Nie udało się wczytać planów. Odśwież stronę, aby spróbować ponownie.';$('#mall-selection').setAttribute('role','alert')}}
render();loadMall();
